    "fold this area away. Nothing in it is lost: the chat keeps its history, the walk its step and the flow its place. Only \"clear\" in the chat deletes anything.": "收起此区域会保留聊天历史、导览步骤和流程位置。只有聊天中的“清空”会删除内容。",
