    "No symbol in the twin yet, so there is no sequence to draw. Open a file and put the caret in a function; the twin follows it, and this tab follows the twin.": "尚未选择符号，无法绘制序列。打开文件，将光标移入函数，此标签页会跟随选中符号。",
    "No walk is running. Start one from the atlas menu (\"Choose a starting point\") and its steps appear here.": "尚未开始导览。在图谱菜单中选择起点，步骤将显示在此处。",
    "Nothing was asked in this session yet. Type a question in the command line and press enter; the answer and the cards it was given show up here.": "本次会话尚未提问。在命令行输入问题并按 Enter，此处会显示回答及依据卡片。",
    "No project is open, and this assistant reads a project index. Open one and the expected path against the observed one is drawn here.": "尚未打开项目。此助手需要项目索引；打开后将在此比较预期路径和观察路径。",
    "No project is open, and this view reads a project index. Open one and the reach of a change is drawn here.": "尚未打开项目。此视图需要项目索引；打开后将在此显示变更范围。",
