    "Index a repository": "索引仓库",
    "The server does the indexing; this window only asks. The path has to be a folder the server may read (its workspace boundary applies), and the job runs in the background while you keep reading.": "服务端负责索引，窗口仅发送请求。路径须为服务端有权读取的文件夹；任务在后台运行，不影响继续浏览。",
