    "Index jobs since the server started": "服务端启动以来的索引任务",
    "read from GET /api/index-status, asked again every {0} s while a job runs": "读取自 GET /api/index-status，任务运行时每 {0} 秒刷新",
    "no job has run yet": "尚未运行过任务",
    "indexing": "正在索引",
