    "failed: {0}": "失败：{0}",
    "state not known to this panel": "此面板无法识别的状态",
    "Decision record": "决策记录",
    "Open ADR": "打开架构决策",
    "The architecture decision record the server keeps for {0}, as markdown. Saving stores it in the project index; a reindex keeps it.": "服务端为 {0} 保存的 Markdown 架构决策记录。保存会写入项目索引，重新索引后保留。",
    "open a project to read or write its decision record": "打开项目以读取或编写决策记录",
