    "POST /api/adr: store this text for the open project": "POST /api/adr：保存当前项目的文本",
    "saved": "已保存",
    "the project is being indexed right now; save again when the job is done": "项目正在索引，请在任务完成后再次保存",
    "not saved: {0}": "未保存：{0}",
