    "serving this page: pid {0}, {1} MB resident": "页面服务进程：PID {0}，常驻内存 {1} MB",
    "one other codebase-memory-mcp process": "另有 1 个 codebase-memory-mcp 进程",
    "{0} other codebase-memory-mcp processes": "另有 {0} 个 codebase-memory-mcp 进程",
