    "Log tail": "日志末尾",
    "read from GET /api/logs: {0} of {1} lines": "读取自 GET /api/logs：{0} / {1} 行",
    "the log ring is empty": "日志缓冲区为空",
    "the log did not arrive: {0}": "无法获取日志：{0}",
    "Frontend log": "前端日志",
    "read from GET /api/ui-log: {0} of {1} lines of {2}": "读取自 GET /api/ui-log：{2} 的 {0} / {1} 行",
    "Local compatibility export archive: {0}; retained history is read from SQLite.": "本地兼容导出归档：{0}；保留的历史读取自 SQLite。",
