    "Enabling downloads about 566 MB from Hugging Face if the files are not already cached. Model files stay in this browser. Opening this panel makes no download request.": "若未缓存，启用时将从 Hugging Face 下载约 566 MB。模型文件保留在此浏览器中。仅打开面板不会下载。",
    "Requires WebGPU with shader-f16 and enough free GPU memory. Runtime code is bundled with CBM. The local-model sidecar remains available separately.": "需要支持 shader-f16 的 WebGPU 及足够的 GPU 可用内存。运行时代码随 CBM 提供，独立本地模型服务仍可另行使用。",
    "Source is processed on this device. It is not sent to Hugging Face or another inference service.": "源码在此设备处理，不会发送到 Hugging Face 或其他推理服务。",
    "Downloads use a dedicated browser cache. Disable stops the worker; Remove also deletes this model cache. Closing the panel disables the model.": "下载使用专用浏览器缓存。禁用会停止工作线程；删除还会清除模型缓存。关闭面板会禁用模型。",
