    "Doc-code candidates": "文档与代码候选",
    "Score documentation sections against code for doc-code candidates. Automatic: on for full indexes, off for moderate and fast; on or off applies to every mode. Costly on very large repositories; off stores none.": "计算文档章节与代码的匹配分数。自动模式在完整索引中开启，在中等和快速索引中关闭；显式开关作用于全部模式。大型仓库开销较高，关闭后不保存候选。",
