    "Language preference used by subsequent HTTP requests.": "后续 HTTP 请求使用的语言偏好，刷新页面后应用。",
    "HTTP interface": "HTTP 界面",
    "Enable the loopback HTTP interface. Without a legacy config file, a build with embedded assets enables it automatically.": "启用回环 HTTP 界面。无旧配置文件时，含内嵌网页资源的构建会自动启用。",
    "HTTP port": "HTTP 端口",
    "Loopback listener port. The running listener remains on its current port until restart.": "回环监听端口。重启前，运行中的监听器仍使用当前端口。",
