    "Indexing workers": "索引工作线程",
    "Automatic uses available CPU cores and foreground/background policy. Supervisor recovery can still force a single worker.": "自动模式根据 CPU 核心数及前后台策略选择数量。监管进程恢复时仍可强制使用单线程。",
    "Memory budget (MiB)": "内存预算（MiB）",
    "Automatic uses a RAM-dependent fraction; the result remains capped by physical RAM and the daemon hard limit.": "自动模式使用按内存容量计算的比例，仍受物理内存和守护进程硬上限约束。",
    "SQLite mapping bytes": "SQLite 映射字节数",
    "Memory mapping limit for new database connections; zero disables mapping.": "新数据库连接的内存映射上限；设为零禁用映射。",
    "Retained extraction budget (MiB)": "提取保留预算（MiB）",
    "Automatic is the smaller of one eighth of the memory budget and 1024 MiB. Explicit indexing options retain precedence.": "自动值为内存预算的八分之一与 1024 MiB 中较小者。显式索引选项优先。",
    "Retained per-file budget (MiB)": "单文件保留预算（MiB）",
    "Automatic is the smaller of 32 MiB and the total retention budget. Explicit indexing options retain precedence.": "自动值为 32 MiB 与总保留预算中较小者。显式索引选项优先。",
    "Semantic indexing": "语义索引",
