    "Watcher prune grace (seconds)": "监视注册清理宽限（秒）",
    "Grace period before removing stale watcher registrations.": "移除过期监视注册前的宽限时间。",
    "Disable cross-file resolution": "禁用跨文件解析",
    "Disable cross-file LSP resolution. False masks an inherited presence flag, even if its inherited value is zero.": "禁用跨文件 LSP 解析。设为 false 会覆盖继承的存在标志，即使继承值为零。",
    "TypeScript resolver budget": "TypeScript 解析预算",
    "Automatic is 1,000,000 plus 64 times source length; zero means unlimited.": "自动值为 1,000,000 加源码长度的 64 倍；零表示无限制。",
