    "symbols": "符号",
    "LOW": "低",
    "MEDIUM": "中",
    "HIGH": "高",
    "A rule applied to what the index recorded, not a prediction. The sentences beside it are the whole of the reasoning.": "根据索引记录应用规则，不是预测。旁边的说明给出完整推理依据。",
    "reachable from outside the program": "可从程序外部到达",
    "nothing measured on this symbol reached a threshold": "此符号的测量值均未达到阈值",
    "The registration names a handler this change reaches.": "注册信息指定的处理器位于此变更影响范围内。",
    "The registration is written in a file this change reaches. CBM Lens cannot name the handler here, so this is the file and not the function.": "注册信息位于此变更影响范围的文件中。此处无法确定处理器，因此标注文件而非函数。",
    "Nothing in the working tree differs from the baseline.": "工作树与基准没有差异。",
    "it": "该符号",
    "them": "这些符号",
    "{0} from the baseline, and the index holds no symbol in {1}.": "{0}与基准不同，索引中没有{1}中的符号。",
    "file differs": "文件",
    "files differ": "文件",
    "{0} from the baseline, and the index places {1} inside {2}.": "{0}与基准不同，索引在{2}中列出了 {1}。",
    "The analysis scoped the diff to {0}, and the list below is the {1} the index places inside those files.": "差异分析的范围为 {0}，下方列表展示索引在这些文件中列出的 {1}。",
    "declaration": "声明",
    "declarations": "声明",
    "Nothing in the indexed workspace calls those symbols, so the change stops where it is.": "已索引工作区中没有符号调用这些目标，因此变更影响到此为止。",
    "Walking the calls inwards reaches {0} within {1}.": "向调用方遍历，在 {1} 内可到达 {0}。",
    "further symbol": "其他符号",
    "further symbols": "其他符号",
