    "steps": "步骤",
    "No HTTP endpoint CBM Lens recovered is registered in a file this change reaches.": "CBM Lens 识别的 HTTP 端点均未在此变更影响范围内的文件中注册。",
    "{0} registered in a file this change reaches: {1}.": "{0}在此变更影响范围内的文件中注册：{1}。",
    "endpoint is": "端点",
    "endpoints are": "端点",
    "No affected symbol could be checked for test callers.": "无法检查任何受影响符号的测试调用方。",
    "Every affected symbol that was checked has a test caller ({0} in total), so a change here would be noticed.": "所有已检查的受影响符号都有测试调用方（共 {0}），此处变更预计可被相关测试发现。",
    "test caller": "测试调用方",
    "test callers": "测试调用方",
    "No test caller was found for {0}, so a change to {1} would go unnoticed by any automatic check.": "未找到 {0} 的测试调用方，因此对{1}的变更可能无法被现有自动检查发现。",
    "affected symbol": "受影响符号",
    "affected symbols": "受影响符号",
    "Complexity readings were unavailable for {0}, so the level rests on what the analysis could not measure as well as on what it could.": "{0} 的复杂度数据不可用，因此等级同时考虑了已测量内容及无法测量的内容。",
    "Test callers were looked up for the first {0} affected symbols only; the rest were not checked.": "仅检查了前 {0} 个受影响符号的测试调用方，其余尚未检查。",
    "The caller walk stopped at its bound, so the list of what calls this change is a floor and not a total.": "调用方遍历已达到范围上限，因此此列表只表示至少存在的调用方，不代表总数。",
    "What this rests on": "结论依据",
    "the change set the analysis reported, plus the calls into it": "分析报告的变更集及指向它的调用",
    "the whole-project summary, including the routes CBM Lens recovered": "整个项目的摘要，包含 CBM Lens 识别的路由",
    "the per-symbol readings: complexity, and callers flagged as test code": "逐符号数据：复杂度以及标记为测试代码的调用方",
    "What would this change reach?": "此变更会影响什么？",
    "RISK UNRESOLVED": "风险未确定",
    "NO ELEVATED SIGNAL": "未发现升高信号",
    "Some risk inputs are missing. No elevated rule fired; this does not establish low risk.": "缺少部分风险输入，且没有高风险规则被触发；这不代表低风险。",
    "Risk inputs are missing for {0} of {1} symbols. No elevated signal is not evidence of safety. Open an affected file to inspect its revision, dependency paths and local Git evidence.": "{1} 个符号中有 {0} 个缺少风险输入。没有升高信号不代表安全。打开受影响文件可检查版本、依赖路径和本地 Git 依据。",
    "Read from the change set the analysis reports, the calls into it, and the routes CBM Lens recovered. The word on the right is a rule applied to those readings, never a prediction.": "依据分析报告的变更集、指向它的调用及识别的路由。右侧等级是应用规则的结果，不是预测。",
    "Compare against": "比较基准",
    "Working tree": "工作树",
    "Compare the working tree against the last commit, which is what the analysis does when nobody names a point.": "将工作树与最近一次提交比较，这是未指定基准时的默认分析方式。",
    "Since ref": "指定版本以来",
    "Compare the working tree against a named point in history.": "将工作树与指定的历史版本比较。",
