    "Endpoints reached": "影响到的端点",
    "Tests": "测试",
    "The index places no symbol inside the changed files.": "索引未在变更文件中列出任何符号。",
    "Nothing in the indexed workspace calls the changed symbols.": "已索引工作区中没有符号调用变更的目标。",
    "No route CBM Lens recovered is registered in a file this change reaches.": "CBM Lens 识别的路由均未在此变更影响范围内的文件中注册。",
    "Routes were read off the text of {0}.": "路由从 {0} 的文本读取。",
    "indexed source file": "已索引源文件",
