    "Which rules fired": "触发的规则",
    "No rule reached a threshold, so the level is the floor and not a finding.": "没有规则达到阈值，因此此等级表示基础等级，不代表发现了问题。",
    "{0} registered in a file this change reaches.": "{0}在此变更影响范围内的文件中注册。",
