    "What the file around this symbol pulls in": "此符号所在文件的导入项",
    "This sentence is generated from the calls, environment values and error types the index recorded. It is not a docstring and nobody wrote it.": "此句根据索引记录的调用、环境值和错误类型生成，并非文档注释或人工编写的说明。",
    "These are rules applied to what the index recorded, not findings from running the code.": "这些结果是在索引记录上应用规则得出的，不是运行代码后的发现。",
    "This symbol calls nothing that the index resolved.": "索引未解析到此符号的任何出站调用。",
