    "This symbol raises no error type that the index recorded.": "索引未记录此符号抛出任何错误类型。",
    "DATA": "数据",
    "ERRORS": "错误",
    "EFFECTS": "外部作用",
    "Where these are handled is not visible to the index: it records where an error is raised, not where it is caught.": "索引仅记录错误抛出的位置，不记录捕获位置，因此无法得知这些错误在哪里被处理。",
    "No evidence for routes, outbound calls or writes is available in this view for this symbol. Missing evidence does not establish that the symbol has no effects.": "当前视图中没有此符号的路由、出站调用或写入依据。缺少依据不代表符号没有外部作用。",
    "Exposes routes": "暴露的路由",
    "Calls out": "对外调用",
    "new": "新建",
    "This step constructs a class rather than calling a function.": "此步骤构造一个类，而非调用函数。",
    "The index flagged this caller as test code.": "索引将此调用方标记为测试代码。",
    "1 test caller": "1 个测试调用方",
    "{0} test callers": "{0} 个测试调用方",
    "No test callers found (inferred from callers, not from a test relation): decide if this needs a test.": "未找到测试调用方（根据调用方推断，并非测试关系）：请判断是否需要添加测试。",
    "Show what this claim is based on.": "显示此结论的依据。",
    "No citation was recorded for this claim.": "此结论没有记录引用。",
    "no recorded location": "未记录位置",
    "{0}, index generation {1}": "{0}，索引代次 {1}",
    "What this is for": "用途是什么",
    "What it does, in order": "依次执行什么",
    "Who uses it": "谁使用它",
    "What it reads": "它读取什么",
    "What the file brings in": "文件引入了什么",
    "How it can fail": "可能如何失败",
    "What it touches outside": "涉及哪些外部内容",
    "What checks it": "什么会检查它",
    "What to watch out for": "需要注意什么",
    "What happens when it runs": "运行时发生什么",
    "What changed recently": "近期有什么变更",
    "This server hands observed calls to trace and flow answers, not to the twin, so this section stays empty. Recorded runs show up on the hops of the BUG hunt and in the flow; they get into the index through ingest_traces on the command line.": "此服务端将观察调用提供给追踪和流程结果，未提供给符号视图，因此此区域保持空白。运行记录会显示在问题排查步骤和调用流程中，可通过命令行 ingest_traces 导入索引。",
    "The twin carries no version history, so this section stays empty. What a change here would reach is answered by the change scope panel ([c]hange scope), which reads it from detect_changes for the worktree or against a reference you name.": "符号视图不包含版本历史，因此此区域保持空白。变更影响由 [c] 变更范围面板回答，通过 detect_changes 读取工作树或与指定版本比较。",
    "Nothing is missing from the index here: the twin does not answer this lens, and it says so rather than showing an empty list.": "此处并非索引缺失，而是符号视图不支持此分析视角，因此明确说明而不展示空列表。",
    "{0} is a {1}.": "{0} 是一个{1}。",
    "{0} hands work to {1}: {2}.": "{0} 将工作交给 {1}：{2}。",
