    "Left to understand": "尚待理解",
    "% confirmed": "% 已确认",
    "That figure counts what you have confirmed, not what you have looked at. Tick items in the Understanding Checklist to move it.": "此比例仅统计你确认的内容，不统计浏览过的内容。可勾选“理解清单”中的条目以更新比例。",
    "Read the {0} this calls": "阅读此符号调用的 {0}",
