    "Confirm {0} set": "确认已设置 {0}",
    "configuration value is": "配置值",
    "configuration values are": "配置值",
    "Know the shape of {0}": "了解 {0} 的结构",
    "Know the shapes of the {0} this names": "了解此符号指定的 {0} 的结构",
    "type": "类型",
    "types": "类型",
    "Read the {0} this constructs": "阅读此处构造的 {0}",
    "classes": "类",
    "Re-read the 1 test that covers this": "重新阅读覆盖此符号的 1 个测试",
    "Re-read the {0} tests that cover this": "重新阅读覆盖此符号的 {0} 个测试",
    "No test callers found: decide if this needs a test": "未找到测试调用方：请判断是否需要添加测试",
    "Walk the places that answer this, one stop at a time.": "逐个浏览回答此问题的位置。",
    "Stop {0} of {1}": "第 {0} / {1} 站",
    "Done": "完成",
    "End the walk. Everything you have already been taken to stays marked as explored.": "结束导览，已访问内容仍标记为已浏览。",
    "What this symbol does is mostly what it delegates to. This is one of the places it hands work to.": "此符号的主要行为来自委托执行。这里是它交出工作的位置之一。",
    "This is where the failure comes from. Reading it is how you find out what a caller has to survive.": "这里是失败来源。阅读它可了解调用方必须处理的情况。",
    "Someone depends on this. What they expect is the constraint on any change you make here.": "有代码依赖此符号，其预期行为约束了你在此处的修改。",
    "This value comes from the environment, so it is set outside the code and fails only where it is missing.": "此值来自运行环境，在代码外部设置，缺失时才会导致失败。",
    "This is a shape the symbol assumes it was handed. Knowing it is how you tell a valid input from an invalid one.": "此符号假定接收到这种结构。了解它有助于区分有效与无效输入。",
    "This class is constructed here rather than called, so reading it is a separate obligation from following a call.": "此处构造该类，而非调用普通函数，因此阅读类定义与跟随调用是不同的待办项。",
    "A test is the shortest available description of what this is supposed to do.": "测试通常是了解预期行为最简短的现有说明。",
    "This is one of the places the checklist points at for this question.": "这是清单为此问题指定的位置之一。",
    "A recording has been imported and none of it passes through this symbol.": "已导入运行记录，但其中没有调用经过此符号。",
    "{0} observed {1}, {2} {3} in all.": "已观察到 {0} {1}，共 {2} {3}。",
    "not in the index": "索引中不存在",
    "The recording holds this call and the analyzer records no such call from this symbol.": "运行记录包含此调用，但分析器没有记录此符号发起相应调用。",
    "Read from an imported recording, not from the index. CBM Lens did not watch this run.": "读取自导入的运行记录，并非索引。CBM Lens 未监视此次运行。",
    "runtime": "运行时",
    "This citation comes from an imported recording, not from the analyzer.": "此引用来自导入的运行记录，并非分析器。",
    "Index generation changed while reading coverage. Run the local diagnosis again.": "读取覆盖信息时索引代次发生变化，请重新运行本地诊断。",
    "The daemon returned no root coverage scope. Coverage completeness is unknown.": "守护进程未返回根目录覆盖范围，覆盖完整性未知。",
    "File is outside the indexed inventory.": "文件不在已索引清单中。",
    "No complete module span or indexed code range is available.": "没有可用的完整模块范围或索引代码范围。",
    "Indexed code exceeds the source limit.": "索引代码超过源码上限。",
    "Indexed code range changed while reading.": "读取时索引代码范围发生变化。",
    "Source exceeds the inspection limit.": "源码超过检查上限。",
    "Source page is unavailable.": "源码分页不可用。",
    "Source is incomplete.": "源码不完整。",
    "Source pages changed while reading.": "读取过程中源码分页发生变化。",
    "Source exceeds the 2,000-line inspection limit.": "源码超过 2,000 行检查上限。",
    "YAML structure exceeds the analysis limit": "YAML 结构超过分析上限",
    "YAML aliases are not supported": "不支持 YAML 别名",
    "YAML merge keys are not supported": "不支持 YAML 合并键",
    "YAML mapping keys must be strings": "YAML 映射键必须为字符串",
    "Repository map response has no graph snapshot metadata.": "仓库映射响应没有图快照元数据。",
    "Repository map returned HTTP {0}.": "仓库映射返回 HTTP {0}。",
    "Architecture response is missing a collection.": "架构响应缺少集合。",
    "This server returned an unsupported architecture response.": "服务端返回了不支持的架构响应。",
    "Invalid architecture retry interval.": "架构重试间隔无效。",
    "Invalid architecture error.": "架构错误信息无效。",
    "This server returned an unsupported architecture projection.": "服务端返回了不支持的架构投影。",
    "Architecture evidence has an invalid shape.": "架构依据格式无效。",
    "Clipboard unavailable": "剪贴板不可用",
    "The model returned an invalid token count.": "模型返回的 token 数量无效。",
    "Unload the current model before changing models.": "更换模型前请先卸载当前模型。",
    "WebGPU is unavailable in this browser. Use a browser with WebGPU enabled. No model was downloaded.": "此浏览器不支持 WebGPU，请使用已启用 WebGPU 的浏览器。未下载模型。",
    "This model needs WebGPU with shader-f16 support. No model was downloaded.": "此模型需要支持 shader-f16 的 WebGPU。未下载模型。",
    "Browser model storage is unavailable. Use a secure localhost browser session.": "浏览器模型存储不可用，请使用安全的 localhost 浏览器会话。",
    "Load a browser model before sending a message.": "发送消息前请先加载浏览器模型。",
    "The conversation contains an invalid message.": "对话包含无效消息。",
    "Invalid generation profile.": "生成配置无效。",
    "Invalid output token limit. Use an integer from 1 to {0}.": "输出 token 上限无效，请使用 1 至 {0} 的整数。",
    "This conversation uses {0} input tokens. The browser limit is {1}, including {2} reserved for the answer. Remove earlier messages or attach a smaller selection; no code was truncated.": "此对话使用 {0} 个输入 token，浏览器上限为 {1}（含为回答保留的 {2} 个）。请移除早期消息或缩小选择范围，代码未被截断。",
    "The model returned no answer.": "模型未返回回答。",
    "Chat history bounds must be positive integers.": "聊天历史上限必须为正整数。",
    "Chat history contains invalid snapshot data.": "聊天历史包含无效快照数据。",
    "Unknown browser model. Choose a model from the catalog.": "未知的浏览器模型，请从列表中选择。",
    "the local model is denied by the project policy, so the answer below is built from the cards and nothing was sent.": "项目策略已禁用本地模型，下方回答由依据卡片构建，未发送任何内容。",
    "the local model is on, but nothing answers on 127.0.0.1:{0}; the answer below is built from the cards.": "本地模型已开启，但 127.0.0.1:{0} 没有响应；下方回答由依据卡片构建。",
    "Clipboard unavailable; select the draft and copy it manually.": "剪贴板不可用，请选中草稿手动复制。",
