    "Directory ancestry determines placement. Connections still come from the indexed graph. Representatives provide location hints when no directory group is reported.": "目录层级决定放置位置，连接仍来自索引图。没有目录分组时，代表项提供位置线索。",
    "Ring area follows log(1 + visible links), relative to the busiest item in this view. Each directed relationship type counts once; this is visual load, not runtime activity.": "圆环面积按 log(1 + 可见连接数) 相对当前最繁忙项缩放，每种有向关系类型计一次。这反映视觉负载，不代表运行活动。",
