    "Changes may continue while this view is open. Refresh before relying on the scope. File-level selection analyzes all indexed declarations, not only edited lines.": "此视图打开时变更仍可能继续。依赖其范围前请刷新。文件级选择会分析全部已索引声明，不局限于编辑行。",
