    "Inspect the nearest dependent paths and check the interfaces used by their callers or importers.": "检查最近的依赖路径，以及调用方或导入方使用的接口。",
    "Review and run the {0} indexed test candidate{1} that reach the selection. Test-file classification is heuristic.": "检查并运行可到达此选择的 {0} 个索引测试候选{1}。测试文件分类基于启发式判断。",
    "No test dependency was found within this walk. Search for integration tests and add a focused regression check; this is not a coverage measurement.": "此次遍历未找到测试依赖。请查找集成测试并添加针对性回归检查；此结果不代表覆盖率测量。",
    "Compare the local change with the indexed source and reindex before relying on absence of downstream findings.": "将本地变更与索引源码比较；依赖“未发现下游影响”的结论前请重新索引。",
    "Inspect the linked local commit evidence for repeated co-changes; shared commits alone do not establish a dependency.": "检查链接的本地提交依据，确认反复出现的共同变更；仅有共同提交不能确定依赖。",
    "Commit hash unavailable": "提交哈希不可用",
