    "Its path names it as a way into the program, so a run starts somewhere in here.": "路径表明它是程序入口，因此运行会从此处某个位置开始。",
    "Its path names it as routing, so what it holds is the mapping from something arriving to the code that answers it.": "路径表明它承担路由职责，将到达的请求映射到处理代码。",
    "Its path names it as a service, so what it holds sits between the ways in and the pieces they lean on.": "路径表明它属于服务，位于入口与其依赖的组件之间。",
    "Its path names it as storage, so what it holds is where data is read and written.": "路径表明它承担存储职责，在此读取和写入数据。",
    "Its path names it as configuration, so the values it deals in are set outside the code and read from here.": "路径表明它属于配置，相关值在代码外部设置，再从此读取。",
    "Its path names it as types, so what it holds is shapes other files agree on rather than behaviour.": "路径表明它定义类型，即其他文件共同遵循的结构，而非行为。",
    "Its path names it as shared helpers, so what it holds is reached from several places and depends on little.": "路径表明它是共享辅助代码，会从多处被访问且自身依赖较少。",
    "Its path names it as a test, so what it holds is the shortest written description of what the code it exercises is supposed to do.": "路径表明它属于测试，描述了被测代码的预期行为。",
    "Its path says nothing about its role. The index places its group in the entry layer.": "路径未体现职责，索引将此分组放在入口层。",
